static double interp2d(const double table[25][25], double vgs, double vds) {
    // Clamp to table range
    if (vgs < VGS_MIN) vgs = VGS_MIN;
    if (vgs > VGS_MAX) vgs = VGS_MAX;
    if (vds < VDS_MIN) vds = VDS_MIN;
    if (vds > VDS_MAX) vds = VDS_MAX;
    
    double fi = (vgs - VGS_MIN) / (VGS_MAX - VGS_MIN) * (N_VGS - 1);
    double fj = (vds - VDS_MIN) / (VDS_MAX - VDS_MIN) * (N_VDS - 1);
    int i = (int)fi; if (i >= N_VGS-1) i = N_VGS-2;
    int j = (int)fj; if (j >= N_VDS-1) j = N_VDS-2;
    double di = fi - i, dj = fj - j;
    
    return table[i][j]*(1-di)*(1-dj) + table[i+1][j]*di*(1-dj) +
           table[i][j+1]*(1-di)*dj + table[i+1][j+1]*di*dj;
}

extern "C" int vae_eval(VaeState* s, double* F, double* Q) {
    memset(F, 0, 16*sizeof(double));
    memset(Q, 0, 16*sizeof(double));
    double vgs = s->V[1] - s->V[2]; // VG - VS
    double vds = s->V[0] - s->V[2]; // VD - VS
    F[1] = interp2d(IDS_TABLE, vgs, vds);
    return 0;
}

extern "C" void vae_jacobian(VaeState* s, double* dFdV, double* dQdV) {
    memset(dFdV, 0, 16*5*sizeof(double));
    memset(dQdV, 0, 16*5*sizeof(double));
    double vgs = s->V[1] - s->V[2];
    double vds = s->V[0] - s->V[2];
    double gm = interp2d(GM_TABLE, vgs, vds);
    double gds = interp2d(GDS_TABLE, vgs, vds);
    // dF[1]/dV[0] = gds (drain)
    // dF[1]/dV[1] = gm (gate)
    // dF[1]/dV[2] = -(gm + gds) (source)
    dFdV[1*5+0] = gds;
    dFdV[1*5+1] = gm;
    dFdV[1*5+2] = -(gm + gds);
}

